package com.example.rokidgeminisecretary;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
final class MaintenanceBackupUi {
 static final int EXPORT=7621,IMPORT=7622;final MainActivity owner;final ReliabilityDialog ui;byte[] encrypted;char[] password;String lease="";boolean working,closed;
 MaintenanceBackupUi(MainActivity c){owner=c;ui=new ReliabilityDialog(c);}
 synchronized void start()throws Exception{if(!lease.isEmpty()||owner.maintenanceBackup!=null&&MaintenanceLease.owns(owner.maintenanceBackup.lease))throw new IOException("保守処理が進行中です。先のファイル選択を完了または中止してください");lease=MaintenanceLease.acquire(owner,"backup");closed=false;owner.maintenanceBackup=this;}
 synchronized void wipe(){if(encrypted!=null)Arrays.fill(encrypted,(byte)0);encrypted=null;if(password!=null)Arrays.fill(password,'\0');password=null;}
 synchronized void end(String phase){wipe();MaintenanceLease.finish(owner,lease,phase);lease="";working=false;}
 synchronized void clear(){closed=true;wipe();if(!working)end("CANCELLED");}
 void show(){LinearLayout b=ui.box();ui.text(b,"メモ・記憶の参照コピー・保守画面の表示設定を選んで暗号化します。写真・音声・動画・認証設定・実行待ち命令は含みません。パスフレーズを忘れると復元できません。クラウドの保存先を選ぶ場合、その提供元に暗号化ファイルを保存します。");EditText pass=ui.field(b,"パスフレーズ（12〜128文字）","",128);pass.setInputType(129);CheckBox notes=new CheckBox(owner),memory=new CheckBox(owner),settings=new CheckBox(owner);notes.setText("有効なメモ（履歴・ごみ箱を除く）");memory.setText("記憶の参照コピー");settings.setText("保守画面の表示設定");notes.setChecked(true);memory.setChecked(true);settings.setChecked(true);b.addView(notes);b.addView(memory);b.addView(settings);
 ui.button(b,"選んだ対象を暗号化保存",()->{char[] phrase=pass.getText().toString().toCharArray();JSONArray selected=selection(notes,memory,settings);try{PortableBackup.password(phrase);start();synchronized(this){working=true;}}catch(Exception e){Arrays.fill(phrase,'\0');ui.confirm(e.getMessage(),()->{});return;}pass.setText("");ui.work(()->{byte[] data=null;try{JSONObject doc=PortableBackup.snapshot(owner,selected);data=PortableBackup.seal(doc,phrase);synchronized(this){if(closed||owner.isDestroyed())throw new IOException("画面が閉じられました。保存していません");encrypted=data;data=null;MaintenanceLease.stage(owner,lease,"PICKER");working=false;}return PortableBackup.preview(doc);}catch(Exception e){end("FAILED");throw e;}finally{Arrays.fill(phrase,'\0');if(data!=null)Arrays.fill(data,(byte)0);}},v->{try{owner.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/octet-stream").putExtra(Intent.EXTRA_TITLE,"loki-backup-"+java.time.LocalDate.now()+".lokibak"),EXPORT);}catch(Exception e){end("FAILED");ui.confirm("保存先を開けませんでした",()->{});}});});
 ui.button(b,"ファイルを選んで復元内容を確認",()->{char[] phrase=pass.getText().toString().toCharArray();boolean acquired=false;try{PortableBackup.password(phrase);start();acquired=true;synchronized(this){password=phrase;MaintenanceLease.stage(owner,lease,"PICKER");}pass.setText("");owner.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),IMPORT);}catch(Exception e){Arrays.fill(phrase,'\0');if(acquired)end("FAILED");ui.confirm(e.getMessage(),()->{});}});
 ui.button(b,"復元した記憶資料を読む",()->ui.work(()->ReviewStore.read(owner,"restored-memory"),v->{LinearLayout refs=ui.box();ui.text(refs,"確認用資料です。AIに自動同期しません。次回の記憶復元で入れ替わります。");JSONArray rows=v.optJSONArray("items");for(int i=0;rows!=null&&i<rows.length();i++){JSONObject row=rows.optJSONObject(i);ui.text(refs,row.optString("topic")+"\n"+row.optString("text"));}ui.display("復元した記憶資料",refs);}));ui.button(b,"保守処理の状態を確認",()->ui.work(()->MaintenanceLease.status(owner),v->ui.confirm("処理："+v.optString("kind","記録なし")+" / "+v.optString("phase","未実行")+"\n途中終了の場合は復元先を確認し、事前検査からやり直してください。自動再開しません。",()->{})));ui.display("暗号化バックアップ・復元",b);}
 static JSONArray selection(CheckBox notes,CheckBox memory,CheckBox settings){JSONArray a=new JSONArray();if(notes.isChecked())a.put("notes");if(memory.isChecked())a.put("memory");if(settings.isChecked())a.put("settings");return a;}
 void result(int code,int result,Intent data){if(code!=EXPORT&&code!=IMPORT)return;if(result!=Activity.RESULT_OK||data==null||data.getData()==null){clear();return;}android.net.Uri uri=data.getData();try{MaintenanceLease.stage(owner,lease,"RUNNING");}catch(Exception e){clear();ui.confirm(e.getMessage(),()->{});return;}if(code==EXPORT){byte[] payload;synchronized(this){payload=encrypted;encrypted=null;working=true;}if(payload==null){end("FAILED");return;}ui.work(()->{boolean success=false;try{OutputStream stream=owner.getContentResolver().openOutputStream(uri,"w");if(stream==null)throw new IOException("保存先を開けません");try(OutputStream out=stream){out.write(payload);out.flush();}success=true;return new JSONObject().put("message","暗号化ファイルを書き込みました。復元確認で内容を確認してください");}finally{Arrays.fill(payload,(byte)0);end(success?"COMPLETED":"FAILED");}},v->ui.confirm(v.optString("message"),()->{}));}else{char[] phrase;synchronized(this){phrase=password;password=null;working=true;}if(phrase==null){end("FAILED");return;}ui.work(()->{boolean success=false;try{JSONObject doc=PortableBackup.open(PortableBackup.read(owner.getContentResolver().openInputStream(uri)),phrase);success=true;return doc;}finally{Arrays.fill(phrase,'\0');end(success?"COMPLETED":"FAILED");}},this::review);}}
 void review(JSONObject doc){LinearLayout b=ui.box();CheckBox notes=new CheckBox(owner),memory=new CheckBox(owner),settings=new CheckBox(owner);notes.setText("メモを別IDのコピーとして追加（既存は上書きしない）");memory.setText("記憶を復元資料へ保存（AIへ自動同期しない）");settings.setText("この保守画面の表示設定を入れ替える");notes.setEnabled(doc.has("notes"));memory.setEnabled(doc.has("memory"));settings.setEnabled(doc.has("settings"));b.addView(notes);b.addView(memory);b.addView(settings);ui.text(b,"作成日時："+new Date(doc.optLong("at"))+"\n復元対象を選んでください。同じアーカイブのメモを再復元しても重複追加せず、既に編集・削除したコピーを上書きしません。複数カテゴリは順に保存し、途中失敗時は既存データを保持します。");JSONArray all=doc.optJSONArray("notes");for(int i=0;all!=null&&i<all.length();i++)ui.text(b,"メモ："+all.optJSONObject(i).optString("text"));all=doc.optJSONArray("memory");for(int i=0;all!=null&&i<all.length();i++){JSONObject row=all.optJSONObject(i);ui.text(b,"記憶資料："+row.optString("topic")+"\n"+row.optString("text"));}if(doc.has("settings"))ui.text(b,"表示設定："+doc.optJSONObject("settings"));ui.button(b,"選んだ内容だけ復元",()->{JSONArray selected=selection(notes,memory,settings);if(selected.length()==0){ui.confirm("復元対象を選んでください",()->{});return;}ui.work(()->RestoreInspection.inspect(owner,doc,selected),plan->{LinearLayout preview=ui.box();ui.text(preview,"追加メモ "+plan.optInt("notesToAdd")+"件 / 復元済みID "+plan.optInt("alreadyRestored")+"件 / 同じ本文 "+plan.optInt("sameTextCount")+"件\n復元後の有効メモ "+plan.optInt("activeAfter")+" / 100件、ごみ箱込み "+plan.optInt("allAfter")+" / 200件\n空き容量 "+plan.optLong("freeBytes")/1048576+" MiB / 必要余裕 "+plan.optLong("requiredFreeBytes")/1048576+" MiB\n表示設定の変更前："+plan.optJSONObject("beforeSettings")+"\n変更後："+plan.optJSONObject("afterSettings")+"\n記憶資料の入替："+plan.optBoolean("memoryReplacement")+"\n"+plan.optString("message"));if(plan.optBoolean("capacityOk"))ui.button(preview,"この事前検査の内容で復元",()->ui.confirm("選んだ内容を復元します。検査後に変更があれば停止します。",()->ui.work(()->RestoreInspection.restore(owner,doc,selected,plan.getString("revision")),v->ui.confirm(v.optString("message"),()->{}))));else ui.text(preview,"件数または空き容量が不足しています。復元は開始できません");ui.display("復元の事前検査",preview);});});ui.display("復元内容の最終確認",b);}
}
